const $=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dateOnly=value=>value?new Date(value).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—';
const dateTime=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const time=value=>value?new Date(value).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'';
const fileToBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').split(',')[1]||'');reader.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));reader.readAsDataURL(file)});
const state={phone:'',data:null,timer:null,userNavigated:false};
const searchForm=$('#tracking-search'),dashboard=$('#tracking-dashboard'),messagesBox=$('#tracking-messages'),messageForm=$('#tracking-message-form'),errorBox=$('#tracking-error'),jumpButton=$('#tracking-jump');

async function request(url,payload){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');return data}
function attachment(message){const url=`/api/conversations/attachment?conversationId=${encodeURIComponent(state.data.conversation.id)}&messageId=${encodeURIComponent(message.id)}`;if(String(message.attachment_mime||'').toLowerCase()==='application/pdf')return `<a class="tracking-file" href="${url}" target="_blank" rel="noopener"><span>PDF</span><strong>${escapeHtml(message.attachment_name||'Documento PDF')}</strong><em>Abrir documento</em></a>`;return `<button class="tracking-image" type="button" data-image="${url}"><img src="${url}" alt="Imagem enviada na conversa" loading="lazy"></button>`}
function messageContent(message){return message.attachment_id?attachment(message):`<span class="tracking-message-text">${escapeHtml(message.body||'').replace(/\r?\n/g,'<br>')}</span>`}
function renderMessages({initial=false}={}){const previousDistance=messagesBox.scrollHeight-messagesBox.clientHeight-messagesBox.scrollTop,follow=initial||previousDistance<70;messagesBox.innerHTML=(state.data.messages||[]).map(message=>{const customer=String(message.sender_type).toUpperCase()==='CLIENTE',sender=!customer&&message.sender_name?`${escapeHtml(message.sender_name)} · `:'';return `<article class="tracking-message ${customer?'customer':''}" data-message-id="${message.id}">${messageContent(message)}<small>${sender}${time(message.created_at)}</small></article>`}).join('')||'<p class="tracking-empty-message">A conversa será exibida aqui.</p>';if(follow)requestAnimationFrame(()=>{messagesBox.scrollTop=messagesBox.scrollHeight;jumpButton.hidden=true});else jumpButton.hidden=false}
function renderQuote(){const quote=state.data.quote,card=$('#tracking-quote'),empty=$('#tracking-no-quote');card.hidden=!quote;empty.hidden=Boolean(quote);if(!quote)return;const address=[quote.endereco,quote.bairro,quote.cidade].filter(Boolean).join(' · '),cancelled=quote.status_orcamento==='CANCELADO';card.innerHTML=`<div class="quote-top"><div><small>ORÇAMENTO DO ATENDIMENTO #${quote.numero_atendimento}</small><strong>${cancelled?'Atendimento cancelado':'Agendamento confirmado'}</strong></div><span class="quote-status ${cancelled?'cancelled':''}">${cancelled?'Orçamento cancelado':quote.status_pag_cliente==='PAGO'?'Pagamento confirmado':'Orçamento gerado'}</span></div><div class="quote-grid"><div class="quote-data wide"><span>Serviço</span><strong>${escapeHtml(quote.descricao_servico)}</strong></div><div class="quote-data"><span>Data agendada</span><strong>${dateOnly(quote.agendado_para)}</strong></div><div class="quote-data"><span>Valor</span><strong>${money(quote.valor)}</strong></div><div class="quote-data wide"><span>Local do serviço</span><strong>${escapeHtml(address)}${quote.referencia?`<br><small>Referência: ${escapeHtml(quote.referencia)}</small>`:''}</strong></div></div>`}
function renderJourney(){const data=state.data,badge=$('#tracking-live-badge');badge.textContent=data.trackingLive?'Deslocamento em andamento':'Atualização automática';badge.classList.toggle('live',data.trackingLive);const destination=data.quote?[data.quote.bairro,data.quote.cidade].filter(Boolean).join(' · '):'Destino será exibido após o orçamento';$('#tracking-route').innerHTML=`<span class="tracking-route-icon" aria-hidden="true">${data.trackingLive?'➜':'⌂'}</span><div><small>${data.trackingLive?'ACOMPANHAMENTO DO TRAJETO':'DESTINO DO ATENDIMENTO'}</small><strong>${escapeHtml(destination)}</strong></div>`;$('#tracking-steps').innerHTML=(data.tracking||[]).map(step=>`<li class="${step.state}"><span class="tracking-step-dot"></span><div class="tracking-step-copy"><strong>${escapeHtml(step.label)}</strong><small>${escapeHtml(step.description)}</small></div><time class="tracking-step-time">${step.occurredAt?dateTime(step.occurredAt):''}</time></li>`).join('')}
function render({initial=false}={}){const data=state.data;document.body.classList.add('tracking-results-active');dashboard.hidden=false;$('#tracking-ticket').textContent=`#${data.conversation.ticketNumber} · ${data.conversation.customerName}`;$('#tracking-current-status').textContent=data.currentStatus;$('#tracking-updated-at').textContent=dateTime(data.conversation.updatedAt);renderQuote();renderJourney();renderMessages({initial});messageForm.hidden=!data.conversation.canInteract;$('#tracking-closed').hidden=data.conversation.canInteract}
async function loadTracking({initial=false,quiet=false}={}){try{const data=await request('/api/conversations/tracking',{phone:state.phone});const previousIds=(state.data?.messages||[]).map(item=>item.id).join('|'),nextIds=(data.messages||[]).map(item=>item.id).join('|');state.data=data;if(initial||previousIds!==nextIds)render({initial});else{renderQuote();renderJourney();$('#tracking-current-status').textContent=data.currentStatus;$('#tracking-updated-at').textContent=dateTime(data.conversation.updatedAt)}}catch(error){if(!quiet){errorBox.textContent=error.message;dashboard.hidden=true}}}
function startPolling(){clearInterval(state.timer);state.timer=setInterval(()=>{if(!document.hidden&&state.phone)loadTracking({quiet:true})},4000)}
searchForm.addEventListener('submit',async event=>{event.preventDefault();const button=searchForm.querySelector('button[type=submit]');button.disabled=true;errorBox.textContent='';state.phone=$('#tracking-phone').value;try{await loadTracking({initial:true});sessionStorage.setItem('jll_tracking_phone',state.phone);startPolling();dashboard.scrollIntoView({behavior:'smooth',block:'start'})}finally{button.disabled=false}});
messageForm.addEventListener('submit',async event=>{event.preventDefault();const input=messageForm.elements.body,button=messageForm.querySelector('button[type=submit]'),body=input.value.trim();if(!body)return;button.disabled=true;input.value='';try{await request('/api/conversations/message',{conversationId:state.data.conversation.id,body});await loadTracking({quiet:true});messagesBox.scrollTop=messagesBox.scrollHeight}catch(error){input.value=body;errorBox.textContent=error.message}finally{button.disabled=false}});
$('#tracking-attach').addEventListener('click',()=>$('#tracking-file').click());$('#tracking-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4*1024*1024){errorBox.textContent='Envie uma imagem JPEG, PNG ou WebP com até 4 MB.';event.target.value='';return}const button=$('#tracking-attach');button.disabled=true;try{const data=await fileToBase64(file);await request('/api/conversations/photo',{conversationId:state.data.conversation.id,fileName:file.name,mimeType:file.type,data});await loadTracking({quiet:true});messagesBox.scrollTop=messagesBox.scrollHeight}catch(error){errorBox.textContent=error.message}finally{button.disabled=false;event.target.value=''}});
messagesBox.addEventListener('click',event=>{const image=event.target.closest('[data-image]');if(!image)return;const viewer=$('#tracking-viewer');viewer.querySelector('img').src=image.dataset.image;viewer.hidden=false});$('#tracking-viewer').addEventListener('click',event=>{if(event.target.closest('button')||event.target===$('#tracking-viewer')){$('#tracking-viewer').hidden=true;$('#tracking-viewer img').removeAttribute('src')}});
messagesBox.addEventListener('scroll',()=>{jumpButton.hidden=messagesBox.scrollHeight-messagesBox.clientHeight-messagesBox.scrollTop<18},{passive:true});jumpButton.addEventListener('click',()=>{messagesBox.scrollTo({top:messagesBox.scrollHeight,behavior:'smooth'});jumpButton.hidden=true});
$('#tracking-change-phone').addEventListener('click',()=>{dashboard.hidden=true;document.body.classList.remove('tracking-results-active');clearInterval(state.timer);state.phone='';state.data=null;searchForm.scrollIntoView({behavior:'smooth'});$('#tracking-phone').focus()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.phone)loadTracking({quiet:true})});
document.querySelector('.tracking-quote-link').addEventListener('click',()=>{location.href='/?chat=1'});
const savedPhone=sessionStorage.getItem('jll_tracking_phone');if(savedPhone)$('#tracking-phone').value=savedPhone;
